// Geist (SIL OFL, Vercel) subset to Latin, Cyrillic and the punctuation the card draws, as woff2 data URLs.
// Embedded so the exported PNG renders the same type on any machine; source: Social Board's public/fonts.
export const GEIST_CSS = [
  `@font-face{font-family:"Geist Stats";font-weight:400;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}`,
  `@font-face{font-family:"Geist Stats";font-weight:500;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}`,
  `@font-face{font-family:"Geist Stats";font-weight:600;font-style:normal;font-display:block;src:url(data:font/woff2;base64,) format("woff2")}`,
].join("\n");
